import { Component, ViewChild} from '@angular/core';
import { ModalService } from './Shared/services/modal.service';
import { AuthService } from './Shared/services/auth.service';

import { ShareComponent } from './POC-Components/share/share.component';

@Component({
    selector: 'app-root',
    templateUrl: './app.component.html',
    styleUrls: ['./app.component.css']
})
export class AppComponent {
    title = 'app';
    public searchword!: string ;
    public url!: string;
    public type!: string;
    isAuthenticated: boolean = false;
    public userProfile: any;
    public urlEmit!: string;
    public shareLink!: string;
    public showSharePanel: boolean = false;
    public showUploadDataPanel : boolean = false;
    public showFAQ: boolean = false;
    public showChatrooms:boolean = false;

    
    @ViewChild('modal', { read: false })
    modal!: ShareComponent;
    //public clickedEvent: Event;
    constructor(private modalService: ModalService, public auth:AuthService) {
        this.searchword = "video";
        this.type ="video";
        auth.handleAuthentication();
	}
    openModal(id: string) {
        this.modalService.open(id);
    }
	public click() {
     
	}

    childEventClicked(event: any) {
      
        this.searchword = event.searchword ;
        this.type = event.type;
        this.shareLink ="https://talash.azurewebsites.net" +"?type=" + this.type + "&searchword=" + this.searchword;
      
       
    }
    childEventClicked1(event: string) {

       
        this.url = event[2];
       
        console.log("url in parent  :" + this.url);
    }

    ShowShreLink()
    {
        this.shareLink ="https://talash.azurewebsites.net" +"?type=" + this.type + "&searchword=" + this.searchword;
    }
    

    openModal1() {
        this.modal.open();
    }
    ShowHidePanels(value:string)
    {
        if(value == 'upload')
            {
                this.showUploadDataPanel = true;
                this.showSharePanel = false;
                this.showFAQ = false;
                this.showChatrooms = false;
            } 
        if(value == 'share') 
            {
                this.showSharePanel = true;
                this.showUploadDataPanel = false;
                this.showFAQ = false;
                this.showChatrooms = false;
            }
            if(value == 'faq')
            {
                this.showFAQ = true;
                this.showSharePanel = false;
                this.showUploadDataPanel = false;
                this.showChatrooms = false;
            }
            if (value == 'chatrooms')
            {
                this.showChatrooms = true;
                this.showFAQ = false;
                this.showSharePanel = false;
                this.showUploadDataPanel = false;

            }
    }
}
<main class="talash-page">
  <header class="talash-hero">
    <img
      class="talash-hero__logo"
      src="https://talashlogs.blob.core.windows.net/other/logo.png"
      alt="Talash"
    />
    <div class="talash-hero__copy">
      <h1>Fast social media search</h1>
      <p>Search, save, share and enjoy hobby content without a cluttered layout.</p>
    </div>
    <div class="talash-hero__account">
      <a *ngIf="auth.isAuthenticated()" [routerLink]="['/profile']" class="account-link">
        <span class="glyphicon glyphicon-user"></span>
        <app-profile></app-profile>
      </a>
      <button *ngIf="auth.isAuthenticated()" type="button" class="btnlogin" (click)="auth.logout()">
        Log out
      </button>
      <button *ngIf="!auth.isAuthenticated()" type="button" class="btnlogin" (click)="auth.login()">
        Login
      </button>
    </div>
  </header>

  <nav class="action-bar" aria-label="Main actions">
    <button type="button" (click)="ShowHidePanels('share')" class="bigbuttons1">Share Video</button>
    <button type="button" (click)="ShowHidePanels('upload')" class="bigbuttons1">Upload Data</button>
    <button type="button" (click)="ShowHidePanels('faq')" class="bigbuttons1">App store</button>
    <button type="button" (click)="ShowHidePanels('chatrooms')" class="bigbuttons1">Chat rooms</button>
    <button type="button" class="bigbuttons1">Buy / Sell Video</button>
  </nav>

  <section *ngIf="showSharePanel" class="utility-panel">
    <button type="button" class="panel-action" (click)="ShowShreLink()">Share</button>
    <span class="share-link">{{ shareLink }}</span>
  </section>

  <section *ngIf="showUploadDataPanel" class="utility-panel">
    <details open>
      <summary>
        Upload content
        <span class="icon" aria-hidden="true">v</span>
      </summary>
      <app-blobupload></app-blobupload>
    </details>
  </section>

  <section *ngIf="showFAQ" class="utility-panel">
    <app-appstore></app-appstore>
  </section>

  <section *ngIf="showChatrooms" class="utility-panel">
    <p>Chat rooms panel</p>
  </section>

  <div class="content-shell">
    <section class="content-main">
      <div class="content-results">
        <my-video *ngIf="type === 'video' || type === 'advancedsearch'" [searchword]="searchword" [type]="type">
        </my-video>

        <app-image-viewer *ngIf="type === 'image'" [searchword]="searchword"></app-image-viewer>

        <div class="result-scroll" *ngIf="type !== 'video' && type !== 'image' && type !== 'advancedsearch'">
          <app-table [searchword]="searchword" [type]="type"></app-table>
        </div>

        <app-preview [url]="url"></app-preview>
      </div>
    </section>

    <aside class="content-sidebar">
      <img
        class="sidebar-gif"
        src="https://giffiles.alphacoders.com/212/21215.gif"
        alt="Animated search graphic"
      />
      <app-events (searchword)="childEventClicked($event)"></app-events>
      <app-fileupload></app-fileupload>
      <p>Check your favourites</p>
      <button type="button" class="panel-action" (click)="openModal1()">My favourites</button>
      <app-modal #modal></app-modal>
    </aside>
  </div>

  <section class="services-section" id="services">
    <h2>Services</h2>
    <div class="services-grid">
      <article>
        <h3>Movies</h3>
        <p>Find interesting movies by Talash instead of only following rating sites.</p>
      </article>
      <article>
        <h3>Chat rooms</h3>
        <p>Use Talash chat spaces instead of moving between meeting tools.</p>
      </article>
      <article>
        <h3>No spam or ads</h3>
        <p>Enjoy videos and images without a noisy browsing experience.</p>
      </article>
      <article>
        <h3>Premium content</h3>
        <p>Store videos, images and chat sessions around your hobbies.</p>
      </article>
    </div>
  </section>

  <section class="packages-section" id="packages">
    <h2>Packages</h2>
    <div class="pricing-grid">
      <article class="pricing-card">
        <h3>Basic</h3>
        <ul>
          <li>Favourites</li>
          <li>Add and search content</li>
          <li>Chat features</li>
          <li>Share favourites</li>
          <li>Tag and filter</li>
          <li>Video download</li>
        </ul>
        <strong>$0</strong>
        <button type="button">Sign Up</button>
      </article>

      <article class="pricing-card pricing-card--highlight">
        <h3>Pro</h3>
        <ul>
          <li>Private content</li>
          <li>Custom search</li>
          <li>Chat features</li>
          <li>Free custom search help</li>
          <li>Video download</li>
        </ul>
        <strong>$20</strong>
        <button type="button">Sign Up</button>
      </article>

      <article class="pricing-card pricing-card--highlight">
        <h3>Pro++</h3>
        <ul>
          <li>Private content</li>
          <li>Custom search</li>
          <li>Chat features</li>
          <li>Sell videos online</li>
          <li>Reports</li>
          <li>Sales leads/contact</li>
        </ul>
        <strong>$100</strong>
        <button type="button">Sign Up</button>
      </article>
    </div>
  </section>
</main>
